PRAGMA foreign_keys=ON; PRAGMA journal_mode=WAL;
        CREATE TABLE IF NOT EXISTS tasks(id INTEGER PRIMARY KEY, config TEXT NOT NULL, enabled INTEGER NOT NULL, next_run INTEGER, running_run INTEGER, manual INTEGER NOT NULL DEFAULT 0, stop INTEGER NOT NULL DEFAULT 0);
        CREATE TABLE IF NOT EXISTS runs(id INTEGER PRIMARY KEY AUTOINCREMENT, task_id INTEGER NOT NULL REFERENCES tasks(id) ON DELETE CASCADE, started INTEGER NOT NULL, ended INTEGER, duration INTEGER, trigger TEXT NOT NULL, status TEXT NOT NULL, exit_code INTEGER, command TEXT NOT NULL, directory TEXT NOT NULL, config TEXT NOT NULL, truncated INTEGER NOT NULL DEFAULT 0);
        CREATE INDEX IF NOT EXISTS scheduled_runs_task ON runs(task_id, id DESC);
